      "reason": "No changes to outcome-domain inclusion, definitions, or importance are reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No changes to processes for selecting results within outcome domains are reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "This study has two outcomes: primary and secondary. The primary outcomes explored the changes in α -diversity and relative abundance of microbial taxa... The secondary outcomes focused on qualitatively summarized β -diversity ordination and linear discriminant analysis effect sizes.",
      "reason": "Primary outcomes are identified as most important (quantitatively meta-analyzed vs qualitatively summarized), but no explicit rationale for their prioritisation is provided."
    }
